 const visibleDoc=rendition.getDocument()!,pointWalker=visibleDoc.createTreeWalker(visibleDoc.body,4);let second:Text|null=null;while(pointWalker.nextNode()){if(pointWalker.currentNode.textContent?.includes("正文二")){second=pointWalker.currentNode as Text;break;}}assert(second,"Second chapter not mounted in shared iframe");const pointRange=visibleDoc.createRange();const pointOffset=second!.data.indexOf("正文二");pointRange.setStart(second!,pointOffset);pointRange.setEnd(second!,pointOffset+1);const pointRect=pointRange.getBoundingClientRect();assert(rendition.getTxtChapterAtPoint(pointRect.left+pointRect.width/2,pointRect.top+pointRect.height/2)?.index===1,"Right-click chapter uses viewport instead of point");cases.push("same-iframe coordinate resolves clicked chapter independently of viewport");
