 await window.electronAPI.invoke("annotation-test-fail-create",true);button("Save").click();await new Promise(r=>setTimeout(r,300));assert(body().value==="quick body"&&(await AnnotationService.list()).records.length===0,"Failed create lost draft or left entity");await window.electronAPI.invoke("annotation-test-fail-create",false);button("Save").click();await wait(async()=>(await AnnotationService.list()).records.length===1,"Quick save failed");
