 await wait(()=>!body(),"Quick editor not closed");select();button("Add to small annotation").click();await wait(()=>host.querySelector('.quick-reference-list button'),"Append selector missing");(host.querySelector('.quick-reference-list button') as HTMLButtonElement).click();await wait(()=>button("Add location")&&!button("Add location").disabled,"Append selection not ready");button("Add location").click();await wait(async()=>(await AnnotationService.get(small.key))!.bindings.length===2,"Append failed");assert((await AnnotationService.list()).records.length===1,"Append duplicated entity");cases.push("append adds relationship without editing or duplicating entity");
 await wait(()=>!body(),"Append not closed");
 const chapter=await AnnotationService.create({bookKey:book.key,kind:"chapter",notes:"last chapter reference"},binding(2));
 render(<QuickEditor request={{kind:"range",binding:{...binding(0),endChapterIndex:2,endChapterId:chapters[2].chapterId}}} onClose={()=>{}}/>);
 await wait(()=>body()&&host.querySelector('.quick-reference-list')?.textContent?.includes("last chapter reference"),"Range references omit end chapter");set(body(),"range draft");(Array.from(host.querySelectorAll<HTMLButtonElement>('.quick-reference-list button')).find(el=>el.textContent?.includes("last chapter"))!).click();await wait(()=>host.querySelector('.annotation-readonly')?.textContent?.includes("last chapter reference"),"Reference full detail missing");assert(body().value==="range draft"&&!host.querySelector('.quick-references textarea'),"Reference replaced or edits range object");cases.push("full-range automatic references open independent read-only detail");
 await window.electronAPI.invoke("annotation-test-preview","native");
 const a=await AnnotationService.create({bookKey:book.key,kind:"small",notes:"island A"},binding(0,0,3));
 const b=await AnnotationService.create({bookKey:book.key,kind:"small",notes:"island B"},binding(0,2,7));
 const c=await AnnotationService.create({bookKey:book.key,kind:"small",notes:"island C"},binding(0,6,10));
 await AnnotationService.bind(a.key,binding(0,1,2));
 const island=await AnnotationService.overlap({bookKey:book.key,bindingId:a.bindings[0].id,sourceTicket:opened.store!.sourceTicket,limit:2});
 const rest=await AnnotationService.overlap({bookKey:book.key,bindingId:a.bindings[0].id,sourceTicket:opened.store!.sourceTicket,offset:2,limit:2});
 const all=[...island.records,...rest.records];assert(island.hasMore&&all.some(r=>r.key===c.key)&&new Set(all.map(r=>r.key)).size===all.length,"Transitive overlap or entity dedupe failed");assert(all.find(r=>r.key===a.key)?.text,"Clicked union quote missing");cases.push("transitive/nested overlap includes off-click interval, dedupes and pages");
 render(<Layer/>);await restoreAnnotations(book,rendition,0);
 const doc=rendition.getDocument()!;assert(doc.querySelector('[data-txt-highlights]')?.textContent?.includes("dotted")||doc.querySelector('.kookit-note')?.getAttribute('style')?.includes('dotted'),"Dotted paint missing");
 assert(doc.body.textContent!.includes("正文一😀 & <tag>"),"Paint changed source text");cases.push("compiled engine dotted cue retains source text");
 const anchor=doc.querySelector<HTMLElement>('.kookit-note')||doc.querySelector<HTMLElement>('[data-txt-block]')||doc.body;
 const click=()=>{const target=doc.createElement("span");target.dataset.key=a.bindings[0].id;target.dataset.bindingId=a.bindings[0].id;target.dataset.noteKey=a.key;const event=new MouseEvent("click",{clientX:100,clientY:100});Object.defineProperty(event,"target",{value:target});annotationTarget(event);};
 click();await wait(()=>host.querySelector('.annotation-floating')?.textContent?.includes("island C"),"Floating union missing");click();await wait(()=>!host.querySelector('.annotation-floating'),"Other annotation click should only close");click();await wait(()=>host.querySelector('.annotation-floating'),"Next click should open");doc.dispatchEvent(new KeyboardEvent("keydown",{key:"Escape",bubbles:true}));await wait(()=>!host.querySelector('.annotation-floating'),"Escape did not close");cases.push("floating union close-first and Escape lifecycle");
 render(<ChapterPicker chapters={Array.from({length:7700},(_,index)=>({index,chapterId:String(index),label:`Chapter ${index}`}))} value={0} onChange={()=>{}} label="Start chapter"/>);button("Start chapter · Chapter 0").click();assert(host.querySelectorAll('.annotation-chapter-viewport button').length<=12,"Chapter controls unbounded");cases.push("7700 chapters mount at most 12 controls");
 let rejected=false;try{await AnnotationService.create({bookKey:book.key,kind:"small",notes:""},binding());}catch{rejected=true;}assert(rejected,"New pure highlight was accepted");cases.push("new pure highlight rejected without deleting legacy records");
 useAppStore.setState(s=>({reader:{...s.reader,annotationLayout:"range"}}));const size=getPageWidth("scroll","1",0,false,false,true);assert(parseFloat(size.pageWidth)<window.innerWidth/3,"Rail and range workspace not deducted");cases.push("shared width calculation reserves rail and panes");
